package com.jarreminder;

import java.util.Arrays;
import net.runelite.api.gameval.NpcID;

enum ButterflyType
{
	RUBY_HARVEST(NpcID.BUTTERFLY_RUBY),
	SAPPHIRE_GLACIALIS(NpcID.BUTTERFLY_GLACIALIS),
	SNOWY_KNIGHT(NpcID.BUTTERFLY_SNOWY),
	BLACK_WARLOCK(NpcID.BUTTERFLY_WARLOCK),
	SUNLIGHT_MOTH(NpcID.MOTH_SUNLIGHT),
	MOONLIGHT_MOTH(NpcID.MOTH_MOONLIGHT, NpcID.MOTH_MOONLIGHT_LOW_WANDER);

	private final int[] npcIds;

	ButterflyType(int... npcIds)
	{
		this.npcIds = npcIds;
	}

	boolean matches(int npcId)
	{
		return Arrays.stream(npcIds).anyMatch(id -> id == npcId);
	}

	boolean isEnabled(JarReminderConfig config)
	{
		switch (this)
		{
			case RUBY_HARVEST:
				return config.rubyHarvest();
			case SAPPHIRE_GLACIALIS:
				return config.sapphireGlacialis();
			case SNOWY_KNIGHT:
				return config.snowyKnight();
			case BLACK_WARLOCK:
				return config.blackWarlock();
			case SUNLIGHT_MOTH:
				return config.sunlightMoth();
			case MOONLIGHT_MOTH:
				return config.moonlightMoth();
			default:
				return false;
		}
	}

	static ButterflyType fromId(int npcId)
	{
		for (ButterflyType type : values())
		{
			if (type.matches(npcId))
			{
				return type;
			}
		}
		return null;
	}
}

package com.jarreminder;

import java.awt.Color;
import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;

@ConfigGroup("jarreminder")
public interface JarReminderConfig extends Config
{
	@ConfigSection(
		name = "Butterflies",
		description = "Butterfly types that require an empty jar",
		position = 0,
		closedByDefault = false
	)
	String butterflySection = "butterflySection";

	@ConfigSection(
		name = "Reminders",
		description = "Head text and the movable reminder box",
		position = 1,
		closedByDefault = false
	)
	String reminderSection = "reminderSection";

	@ConfigItem(
		keyName = "rubyHarvest",
		name = "Ruby harvest",
		description = "Require an empty butterfly jar to catch ruby harvests",
		position = 0,
		section = butterflySection
	)
	default boolean rubyHarvest()
	{
		return true;
	}

	@ConfigItem(
		keyName = "sapphireGlacialis",
		name = "Sapphire glacialis",
		description = "Require an empty butterfly jar to catch sapphire glacialis",
		position = 1,
		section = butterflySection
	)
	default boolean sapphireGlacialis()
	{
		return true;
	}

	@ConfigItem(
		keyName = "snowyKnight",
		name = "Snowy knight",
		description = "Require an empty butterfly jar to catch snowy knights",
		position = 2,
		section = butterflySection
	)
	default boolean snowyKnight()
	{
		return true;
	}

	@ConfigItem(
		keyName = "blackWarlock",
		name = "Black warlock",
		description = "Require an empty butterfly jar to catch black warlocks",
		position = 3,
		section = butterflySection
	)
	default boolean blackWarlock()
	{
		return true;
	}

	@ConfigItem(
		keyName = "sunlightMoth",
		name = "Sunlight moth",
		description = "Require an empty butterfly jar to catch sunlight moths",
		position = 4,
		section = butterflySection
	)
	default boolean sunlightMoth()
	{
		return true;
	}

	@ConfigItem(
		keyName = "moonlightMoth",
		name = "Moonlight moth",
		description = "Require an empty butterfly jar to catch moonlight moths",
		position = 5,
		section = butterflySection
	)
	default boolean moonlightMoth()
	{
		return true;
	}

	@ConfigItem(
		keyName = "blockedMessage",
		name = "Blocked message",
		description = "Text shown above your head when a catch is blocked, and in the movable reminder box",
		position = 0,
		section = reminderSection
	)
	default String blockedMessage()
	{
		return "You need a butterfly jar.";
	}

	@ConfigItem(
		keyName = "netJarReminder",
		name = "Net jar reminder",
		description = "While a butterfly net or magic butterfly net is worn, show the blocked message above the chat until an empty butterfly jar is in the inventory",
		position = 1,
		section = reminderSection
	)
	default boolean netJarReminder()
	{
		return true;
	}

	@ConfigItem(
		keyName = "flashReminder",
		name = "Flash the Reminder Box",
		description = "Makes the reminder box flash between the defined colors",
		position = 2,
		section = reminderSection
	)
	default boolean flashReminder()
	{
		return false;
	}

	@Alpha
	@ConfigItem(
		keyName = "reminderColor",
		name = "Color",
		description = "Reminder box color. One of the two colors used while flashing",
		position = 3,
		section = reminderSection
	)
	default Color reminderColor()
	{
		return new Color(70, 70, 70, 150);
	}

	@Alpha
	@ConfigItem(
		keyName = "reminderFlashColor",
		name = "Flash Color",
		description = "The other reminder box color used while flashing",
		position = 4,
		section = reminderSection
	)
	default Color reminderFlashColor()
	{
		return new Color(255, 0, 0, 150);
	}
}

package com.jarreminder;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.Point;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

public class JarReminderOverlay extends Overlay
{
	@Inject
	private Client client;

	@Inject
	private JarReminderPlugin plugin;

	@Inject
	private JarReminderConfig config;

	@Inject
	JarReminderOverlay()
	{
		setLayer(OverlayLayer.ABOVE_SCENE);
		setPosition(OverlayPosition.DYNAMIC);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!plugin.isOverheadVisible() || !JarReminderPlugin.hasBlockedMessage(config))
		{
			return null;
		}

		final String text = config.blockedMessage();

		final Player localPlayer = client.getLocalPlayer();
		if (localPlayer == null)
		{
			return null;
		}

		graphics.setFont(FontManager.getRunescapeBoldFont());
		final Point point = localPlayer.getCanvasTextLocation(graphics, text, localPlayer.getLogicalHeight() + 40);
		if (point == null)
		{
			return null;
		}

		final int x = point.getX();
		final int y = point.getY();
		graphics.setColor(Color.BLACK);
		graphics.drawString(text, x + 1, y);
		graphics.drawString(text, x - 1, y);
		graphics.drawString(text, x, y + 1);
		graphics.drawString(text, x, y - 1);
		graphics.setColor(Color.WHITE);
		graphics.drawString(text, x, y);
		return null;
	}
}

package com.jarreminder;

import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.ComponentConstants;
import net.runelite.client.ui.overlay.components.LineComponent;

public class JarReminderPanel extends OverlayPanel
{
	private static final int FLASH_PERIOD_CYCLES = 40;

	@Inject
	private Client client;

	@Inject
	private JarReminderPlugin plugin;

	@Inject
	private JarReminderConfig config;

	@Inject
	JarReminderPanel()
	{
		setPosition(OverlayPosition.ABOVE_CHATBOX_RIGHT);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!plugin.isNetReminderVisible() || !JarReminderPlugin.hasBlockedMessage(config))
		{
			return null;
		}

		final String text = config.blockedMessage();

		panelComponent.getChildren().clear();
		panelComponent.getChildren().add(LineComponent.builder()
			.left(text)
			.build());
		if (config.flashReminder())
		{
			panelComponent.setBackgroundColor(client.getGameCycle() % FLASH_PERIOD_CYCLES >= FLASH_PERIOD_CYCLES / 2
				? config.reminderFlashColor()
				: config.reminderColor());
		}
		else
		{
			panelComponent.setBackgroundColor(ComponentConstants.STANDARD_BACKGROUND_COLOR);
		}
		return super.render(graphics);
	}
}

package com.jarreminder;

import com.google.inject.Provides;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.ItemContainer;
import net.runelite.api.MenuEntry;
import net.runelite.api.NPC;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@PluginDescriptor(
	name = "Jar Reminder",
	description = "Block catching butterflies unless you have an empty butterfly jar",
	tags = {"hunter", "butterfly", "jar"}
)
public class JarReminderPlugin extends Plugin
{
	static final long OVERHEAD_DURATION_MS = 3000;

	static boolean hasBlockedMessage(JarReminderConfig config)
	{
		final String message = config.blockedMessage();
		return message != null && !message.trim().isEmpty();
	}
	private static final int[] BUTTERFLY_NET_IDS = {
		ItemID.HUNTING_BUTTERFLY_NET,
		ItemID.II_MAGIC_BUTTERFLY_NET
	};

	@Inject
	private Client client;

	@Inject
	private JarReminderConfig config;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private JarReminderOverlay overlay;

	@Inject
	private JarReminderPanel reminderOverlay;

	private long overheadUntilMs;

	@Override
	protected void startUp()
	{
		overlayManager.add(overlay);
		overlayManager.add(reminderOverlay);
		overheadUntilMs = 0;
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		overlayManager.remove(reminderOverlay);
		overheadUntilMs = 0;
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() != GameState.LOGGED_IN)
		{
			overheadUntilMs = 0;
		}
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		final MenuEntry entry = event.getMenuEntry();
		if (entry == null || !"Catch".equals(entry.getOption()))
		{
			return;
		}

		final NPC npc = entry.getNpc();
		if (npc == null)
		{
			return;
		}

		final ButterflyType type = ButterflyType.fromId(npc.getId());
		if (type == null || !type.isEnabled(config))
		{
			return;
		}

		if (hasButterflyJar())
		{
			return;
		}

		event.consume();
		if (hasBlockedMessage(config))
		{
			overheadUntilMs = System.currentTimeMillis() + OVERHEAD_DURATION_MS;
		}
	}

	boolean isOverheadVisible()
	{
		return System.currentTimeMillis() < overheadUntilMs;
	}

	boolean isNetReminderVisible()
	{
		return config.netJarReminder() && isWearingButterflyNet() && !hasButterflyJar();
	}

	private boolean hasButterflyJar()
	{
		final ItemContainer inventory = client.getItemContainer(InventoryID.INV);
		return inventory != null && inventory.contains(ItemID.BUTTERFLY_JAR);
	}

	private boolean isWearingButterflyNet()
	{
		final ItemContainer worn = client.getItemContainer(InventoryID.WORN);
		if (worn == null)
		{
			return false;
		}

		for (int netId : BUTTERFLY_NET_IDS)
		{
			if (worn.contains(netId))
			{
				return true;
			}
		}
		return false;
	}

	@Provides
	JarReminderConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(JarReminderConfig.class);
	}
}

package com.jarreminder;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class JarReminderPluginTest
{
